      "claim": "Corporate optimization for cost-per-task ignores the degradation of social trust and the loss of human-led institutional accountability.",
      "targets": []
    },
    {
      "claim": "Institutional accountability must remain strictly human to prevent catastrophic systemic collapse.",
      "targets": []
    }
  ],
  "key_assumptions": [
    {
      "assumption": "Autonomous systems will continue to prioritize proxy metrics like cost-efficiency over complex, unquantified human values.",
      "if_wrong": "If alignment technology reliably captures human values, my concern about reward hacking would be mitigated."
    },
    {
      "assumption": "The transition to agent-led labor creates a path dependency that makes rolling back or overriding automated systems prohibitively difficult.",
      "if_wrong": "If systems remain easily reversible, the risk of a 'treacherous turn' would be a manageable friction rather than an existential threat."
    }
  ]
}

